insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900001', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'easy', 'published', 'Uma equipe registra as matrizes $A=\begin{pmatrix}2&-1\\0&3\end{pmatrix}$ e $B=\begin{pmatrix}1&4\\-2&0\end{pmatrix}$. Qual é $A+B$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000011', '40000000-0000-4000-8000-000000900001', 'A', '$\begin{pmatrix}3&3\\-2&3\end{pmatrix}$', 1), ('50000000-0000-4000-8000-000009000012', '40000000-0000-4000-8000-000000900001', 'B', '$\begin{pmatrix}3&-5\\2&3\end{pmatrix}$', 2), ('50000000-0000-4000-8000-000009000013', '40000000-0000-4000-8000-000000900001', 'C', '$\begin{pmatrix}2&-4\\0&0\end{pmatrix}$', 3), ('50000000-0000-4000-8000-000009000014', '40000000-0000-4000-8000-000000900001', 'D', '$\begin{pmatrix}3&4\\-2&3\end{pmatrix}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900001', '50000000-0000-4000-8000-000009000011') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900001', '30000000-0000-4000-8000-000000090001', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000011', '40000000-0000-4000-8000-000000900001', 'A soma de matrizes preserva a posição de cada entrada.', 1), ('60000000-0000-4000-8000-000009000012', '40000000-0000-4000-8000-000000900001', 'Some separadamente as entradas da primeira linha.', 2), ('60000000-0000-4000-8000-000009000013', '40000000-0000-4000-8000-000000900001', 'Confira a entrada inferior esquerda usando $0+(-2)$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900001', '$\begin{pmatrix}3&3\\-2&3\end{pmatrix}$', 'Matrizes de mesma ordem são somadas componente a componente. Nenhuma linha ou coluna muda de posição; por isso cada entrada do resultado combina apenas as entradas correspondentes.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000011', '40000000-0000-4000-8000-000000900001', 'Confirme as dimensões', 'As duas matrizes são $2\times2$, portanto a soma está definida.', 1), ('70000000-0000-4000-8000-000009000012', '40000000-0000-4000-8000-000000900001', 'Some a primeira linha', 'Obtemos $(2+1,-1+4)=(3,3)$.', 2), ('70000000-0000-4000-8000-000009000013', '40000000-0000-4000-8000-000000900001', 'Some a segunda linha', 'Obtemos $(0-2,3+0)=(-2,3)$.', 3), ('70000000-0000-4000-8000-000009000014', '40000000-0000-4000-8000-000000900001', 'Verifique uma entrada', 'A entrada $(2,1)$ é $-2$, confirmando a primeira alternativa.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900002', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'easy', 'published', 'Sem calcular o produto inteiro, determine a entrada $(2,1)$ de $AB$, onde $A=\begin{pmatrix}1&2\\-1&3\end{pmatrix}$ e $B=\begin{pmatrix}4&0\\2&5\end{pmatrix}$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000021', '40000000-0000-4000-8000-000000900002', 'A', '$7$', 1), ('50000000-0000-4000-8000-000009000022', '40000000-0000-4000-8000-000000900002', 'B', '$2$', 2), ('50000000-0000-4000-8000-000009000023', '40000000-0000-4000-8000-000000900002', 'C', '$10$', 3), ('50000000-0000-4000-8000-000009000024', '40000000-0000-4000-8000-000000900002', 'D', '$-4$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900002', '50000000-0000-4000-8000-000009000022') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900002', '30000000-0000-4000-8000-000000090001', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000021', '40000000-0000-4000-8000-000000900002', 'Uma entrada do produto combina uma linha da primeira matriz com uma coluna da segunda.', 1), ('60000000-0000-4000-8000-000009000022', '40000000-0000-4000-8000-000000900002', 'Para $(2,1)$, use a segunda linha de $A$ e a primeira coluna de $B$.', 2), ('60000000-0000-4000-8000-000009000023', '40000000-0000-4000-8000-000000900002', 'O cálculo intermediário deve ter exatamente dois produtos somados.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900002', '$2$', 'A entrada $(i,j)$ de um produto vem do produto escalar da linha $i$ da primeira matriz com a coluna $j$ da segunda. A multiplicação componente a componente de matrizes daria outra operação.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000021', '40000000-0000-4000-8000-000000900002', 'Escolha a linha', 'A segunda linha de $A$ é $(-1,3)$.', 1), ('70000000-0000-4000-8000-000009000022', '40000000-0000-4000-8000-000000900002', 'Escolha a coluna', 'A primeira coluna de $B$ é $(4,2)$.', 2), ('70000000-0000-4000-8000-000009000023', '40000000-0000-4000-8000-000000900002', 'Faça o produto escalar', '$(-1)\cdot4+3\cdot2=-4+6$.', 3), ('70000000-0000-4000-8000-000009000024', '40000000-0000-4000-8000-000000900002', 'Conclua', 'A soma vale $2$, que corresponde à primeira alternativa.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900003', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'easy', 'published', 'Ao escalonar uma matriz, deseja-se zerar o primeiro elemento de $L_2$ sabendo que ele vale $6$ e que o primeiro elemento de $L_1$ vale $2$. Qual operação é adequada?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000031', '40000000-0000-4000-8000-000000900003', 'A', '$L_2\leftarrow 3L_2-L_1$', 1), ('50000000-0000-4000-8000-000009000032', '40000000-0000-4000-8000-000000900003', 'B', '$L_2\leftarrow L_2+3L_1$', 2), ('50000000-0000-4000-8000-000009000033', '40000000-0000-4000-8000-000000900003', 'C', '$L_2\leftarrow L_2-3L_1$', 3), ('50000000-0000-4000-8000-000009000034', '40000000-0000-4000-8000-000000900003', 'D', '$L_1\leftarrow L_1-3L_2$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900003', '50000000-0000-4000-8000-000009000033') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900003', '30000000-0000-4000-8000-000000090002', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000031', '40000000-0000-4000-8000-000000900003', 'Procure um múltiplo do pivô que produza o oposto de $6$.', 1), ('60000000-0000-4000-8000-000009000032', '40000000-0000-4000-8000-000000900003', 'A linha que deve mudar é $L_2$.', 2), ('60000000-0000-4000-8000-000009000033', '40000000-0000-4000-8000-000000900003', 'Confira apenas a primeira entrada: $6-3\cdot2$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900003', '$L_2\leftarrow L_2-3L_1$', 'A operação deve agir sobre toda a segunda linha e transformar sua primeira entrada em zero. Subtrair três vezes a linha do pivô preserva o conjunto de soluções e produz exatamente esse cancelamento.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000031', '40000000-0000-4000-8000-000000900003', 'Identifique o pivô', 'O pivô disponível na primeira linha é $2$.', 1), ('70000000-0000-4000-8000-000009000032', '40000000-0000-4000-8000-000000900003', 'Determine o multiplicador', 'Como $6=3\cdot2$, precisamos subtrair três vezes o pivô.', 2), ('70000000-0000-4000-8000-000009000033', '40000000-0000-4000-8000-000000900003', 'Aplique à linha correta', 'Usamos $L_2\leftarrow L_2-3L_1$ em todas as colunas.', 3), ('70000000-0000-4000-8000-000009000034', '40000000-0000-4000-8000-000000900003', 'Confira o cancelamento', 'Na primeira coluna, $6-3\cdot2=0$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900004', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'easy', 'published', 'Qual par ordenado satisfaz simultaneamente $2x-y=1$ e $x+y=5$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000041', '40000000-0000-4000-8000-000000900004', 'A', '$(3,2)$', 1), ('50000000-0000-4000-8000-000009000042', '40000000-0000-4000-8000-000000900004', 'B', '$(1,4)$', 2), ('50000000-0000-4000-8000-000009000043', '40000000-0000-4000-8000-000000900004', 'C', '$(4,1)$', 3), ('50000000-0000-4000-8000-000009000044', '40000000-0000-4000-8000-000000900004', 'D', '$(2,3)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900004', '50000000-0000-4000-8000-000009000044') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900004', '30000000-0000-4000-8000-000000090003', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000041', '40000000-0000-4000-8000-000000900004', 'Uma solução precisa tornar verdadeiras as duas equações.', 1), ('60000000-0000-4000-8000-000009000042', '40000000-0000-4000-8000-000000900004', 'Use a equação $x+y=5$ para filtrar os candidatos.', 2), ('60000000-0000-4000-8000-000009000043', '40000000-0000-4000-8000-000000900004', 'Depois confira o valor de $2x-y$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900004', '$(2,3)$', 'Resolver ou verificar um sistema significa satisfazer todas as equações ao mesmo tempo. Um par que funciona em apenas uma delas não pertence ao conjunto solução do sistema.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000041', '40000000-0000-4000-8000-000000900004', 'Use a soma', 'Todos os candidatos somam $5$, então precisamos da outra equação.', 1), ('70000000-0000-4000-8000-000009000042', '40000000-0000-4000-8000-000000900004', 'Teste o primeiro par', 'Para $(2,3)$, temos $2\cdot2-3=1$.', 2), ('70000000-0000-4000-8000-000009000043', '40000000-0000-4000-8000-000000900004', 'Confirme a segunda equação', 'Também $2+3=5$.', 3), ('70000000-0000-4000-8000-000009000044', '40000000-0000-4000-8000-000000900004', 'Elimine a ambiguidade', 'Os demais pares não produzem $1$ em $2x-y$, logo a resposta é $(2,3)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900005', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'easy', 'published', 'Um escalonamento terminou em $z=2$, $y-3z=-4$ e $x+y+z=7$. Qual é o valor de $x$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000051', '40000000-0000-4000-8000-000000900005', 'A', '$3$', 1), ('50000000-0000-4000-8000-000009000052', '40000000-0000-4000-8000-000000900005', 'B', '$1$', 2), ('50000000-0000-4000-8000-000009000053', '40000000-0000-4000-8000-000000900005', 'C', '$5$', 3), ('50000000-0000-4000-8000-000009000054', '40000000-0000-4000-8000-000000900005', 'D', '$9$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900005', '50000000-0000-4000-8000-000009000051') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900005', '30000000-0000-4000-8000-000000090003', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000051', '40000000-0000-4000-8000-000000900005', 'Comece pela equação que já isola uma variável.', 1), ('60000000-0000-4000-8000-000009000052', '40000000-0000-4000-8000-000000900005', 'Substitua $z$ na equação que contém $y$.', 2), ('60000000-0000-4000-8000-000009000053', '40000000-0000-4000-8000-000000900005', 'Antes de encontrar $x$, confira se $y=2$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900005', '$3$', 'Em um sistema triangular, a substituição retroativa começa pela última variável e sobe pelas equações. Essa ordem evita criar novas incógnitas e mantém cada etapa determinada.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000051', '40000000-0000-4000-8000-000000900005', 'Leia a última variável', 'A primeira informação direta é $z=2$.', 1), ('70000000-0000-4000-8000-000009000052', '40000000-0000-4000-8000-000000900005', 'Recupere $y$', '$y-3\cdot2=-4$, então $y=2$.', 2), ('70000000-0000-4000-8000-000009000053', '40000000-0000-4000-8000-000000900005', 'Recupere $x$', '$x+2+2=7$, logo $x=3$.', 3), ('70000000-0000-4000-8000-000009000054', '40000000-0000-4000-8000-000000900005', 'Verifique', 'Os valores $(3,2,2)$ satisfazem as três equações apresentadas.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900006', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'easy', 'published', 'A matriz $D=\begin{pmatrix}2&0\\0&-4\end{pmatrix}$ é invertível. Qual é $D^{-1}$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000061', '40000000-0000-4000-8000-000000900006', 'A', '$\begin{pmatrix}1/2&0\\0&1/4\end{pmatrix}$', 1), ('50000000-0000-4000-8000-000009000062', '40000000-0000-4000-8000-000000900006', 'B', '$\begin{pmatrix}1/2&0\\0&-1/4\end{pmatrix}$', 2), ('50000000-0000-4000-8000-000009000063', '40000000-0000-4000-8000-000000900006', 'C', '$\begin{pmatrix}-2&0\\0&4\end{pmatrix}$', 3), ('50000000-0000-4000-8000-000009000064', '40000000-0000-4000-8000-000000900006', 'D', '$\begin{pmatrix}2&0\\0&1/4\end{pmatrix}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900006', '50000000-0000-4000-8000-000009000062') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900006', '30000000-0000-4000-8000-000000090004', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000061', '40000000-0000-4000-8000-000000900006', 'A inversa deve produzir a identidade quando multiplicada por $D$.', 1), ('60000000-0000-4000-8000-000009000062', '40000000-0000-4000-8000-000000900006', 'Em uma matriz diagonal invertível, trate cada entrada diagonal separadamente.', 2), ('60000000-0000-4000-8000-000009000063', '40000000-0000-4000-8000-000000900006', 'O inverso multiplicativo de $-4$ mantém o sinal negativo.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900006', '$\begin{pmatrix}1/2&0\\0&-1/4\end{pmatrix}$', 'Uma matriz diagonal é invertida tomando o recíproco de cada entrada diagonal não nula. As entradas fora da diagonal continuam zero, e o sinal de cada recíproco é preservado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000061', '40000000-0000-4000-8000-000000900006', 'Observe a estrutura', '$D$ é diagonal e suas entradas diagonais são não nulas.', 1), ('70000000-0000-4000-8000-000009000062', '40000000-0000-4000-8000-000000900006', 'Inverta a primeira entrada', 'O recíproco de $2$ é $1/2$.', 2), ('70000000-0000-4000-8000-000009000063', '40000000-0000-4000-8000-000000900006', 'Inverta a segunda entrada', 'O recíproco de $-4$ é $-1/4$.', 3), ('70000000-0000-4000-8000-000009000064', '40000000-0000-4000-8000-000000900006', 'Confira o produto', '$D D^{-1}=\operatorname{diag}(1,1)=I$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900007', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'medium', 'published', 'Se $A=\begin{pmatrix}1&1\\0&1\end{pmatrix}$ e $AX=\begin{pmatrix}3&1\\2&4\end{pmatrix}$, qual é $X$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000071', '40000000-0000-4000-8000-000000900007', 'A', '$\begin{pmatrix}5&5\\2&4\end{pmatrix}$', 1), ('50000000-0000-4000-8000-000009000072', '40000000-0000-4000-8000-000000900007', 'B', '$\begin{pmatrix}1&1\\2&4\end{pmatrix}$', 2), ('50000000-0000-4000-8000-000009000073', '40000000-0000-4000-8000-000000900007', 'C', '$\begin{pmatrix}1&-3\\2&4\end{pmatrix}$', 3), ('50000000-0000-4000-8000-000009000074', '40000000-0000-4000-8000-000000900007', 'D', '$\begin{pmatrix}3&1\\-1&3\end{pmatrix}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900007', '50000000-0000-4000-8000-000009000073') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900007', '30000000-0000-4000-8000-000000090001', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000071', '40000000-0000-4000-8000-000000900007', 'Para isolar $X$, multiplique à esquerda por $A^{-1}$.', 1), ('60000000-0000-4000-8000-000009000072', '40000000-0000-4000-8000-000000900007', 'A inversa de $A$ troca o $1$ superior direito por $-1$.', 2), ('60000000-0000-4000-8000-000009000073', '40000000-0000-4000-8000-000000900007', 'Confira o resultado multiplicando a primeira linha de $A$ por cada coluna de $X$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900007', '$\begin{pmatrix}1&-3\\2&4\end{pmatrix}$', 'Como a multiplicação matricial não é comutativa, a inversa deve atuar no mesmo lado em que aparece $A$. Multiplicar à esquerda por $A^{-1}$ preserva a ordem e isola $X$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000071', '40000000-0000-4000-8000-000000900007', 'Encontre a inversa', '$A^{-1}=\begin{pmatrix}1&-1\\0&1\end{pmatrix}$.', 1), ('70000000-0000-4000-8000-000009000072', '40000000-0000-4000-8000-000000900007', 'Isole a incógnita', 'De $AX=B$, obtemos $X=A^{-1}B$.', 2), ('70000000-0000-4000-8000-000009000073', '40000000-0000-4000-8000-000000900007', 'Calcule o produto', '$X=\begin{pmatrix}1&-1\\0&1\end{pmatrix}\begin{pmatrix}3&1\\2&4\end{pmatrix}=\begin{pmatrix}1&-3\\2&4\end{pmatrix}$.', 3), ('70000000-0000-4000-8000-000009000074', '40000000-0000-4000-8000-000000900007', 'Verifique a ordem', 'Multiplicar $A$ por essa matriz recupera exatamente o lado direito.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900008', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'medium', 'published', 'Após operações elementares, a matriz aumentada de um sistema é $\begin{pmatrix}1&2&|&3\\0&0&|&1\end{pmatrix}$. O que se conclui?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000081', '40000000-0000-4000-8000-000000900008', 'A', 'O sistema possui uma variável livre.', 1), ('50000000-0000-4000-8000-000009000082', '40000000-0000-4000-8000-000000900008', 'B', 'O sistema tem solução única.', 2), ('50000000-0000-4000-8000-000009000083', '40000000-0000-4000-8000-000000900008', 'C', 'O sistema é homogêneo.', 3), ('50000000-0000-4000-8000-000009000084', '40000000-0000-4000-8000-000000900008', 'D', 'O sistema é inconsistente.', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900008', '50000000-0000-4000-8000-000009000084') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900008', '30000000-0000-4000-8000-000000090002', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000081', '40000000-0000-4000-8000-000000900008', 'Traduza cada linha novamente como uma equação.', 1), ('60000000-0000-4000-8000-000009000082', '40000000-0000-4000-8000-000000900008', 'Observe especialmente a linha cujo lado esquerdo é todo zero.', 2), ('60000000-0000-4000-8000-000009000083', '40000000-0000-4000-8000-000000900008', 'Uma igualdade do tipo $0=c$ só pode ser satisfeita quando $c=0$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900008', 'O sistema é inconsistente.', 'A segunda linha representa uma afirmação impossível, $0=1$. Operações elementares preservam o conjunto de soluções; portanto a contradição mostra que o sistema original não possui solução.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000081', '40000000-0000-4000-8000-000000900008', 'Leia a primeira linha', 'Ela representa $x+2y=3$.', 1), ('70000000-0000-4000-8000-000009000082', '40000000-0000-4000-8000-000000900008', 'Leia a segunda linha', 'Ela representa $0x+0y=1$, isto é, $0=1$.', 2), ('70000000-0000-4000-8000-000009000083', '40000000-0000-4000-8000-000000900008', 'Interprete a contradição', 'Nenhum par de números torna $0=1$ verdadeiro.', 3), ('70000000-0000-4000-8000-000009000084', '40000000-0000-4000-8000-000000900008', 'Conclua sobre o sistema', 'O conjunto solução é vazio, logo o sistema é inconsistente.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900009', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'medium', 'published', 'O sistema $kx+y=5$ e $x-y=1$ deve ter $(2,1)$ como solução. Qual valor de $k$ satisfaz essa exigência?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000091', '40000000-0000-4000-8000-000000900009', 'A', '$k=2$', 1), ('50000000-0000-4000-8000-000009000092', '40000000-0000-4000-8000-000000900009', 'B', '$k=3$', 2), ('50000000-0000-4000-8000-000009000093', '40000000-0000-4000-8000-000000900009', 'C', '$k=1$', 3), ('50000000-0000-4000-8000-000009000094', '40000000-0000-4000-8000-000000900009', 'D', '$k=-2$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900009', '50000000-0000-4000-8000-000009000091') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900009', '30000000-0000-4000-8000-000000090003', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000091', '40000000-0000-4000-8000-000000900009', 'Uma solução prescrita pode ser substituída diretamente nas equações.', 1), ('60000000-0000-4000-8000-000009000092', '40000000-0000-4000-8000-000000900009', 'A segunda equação serve para confirmar que o par é admissível.', 2), ('60000000-0000-4000-8000-000009000093', '40000000-0000-4000-8000-000000900009', 'Na primeira equação, obtenha uma equação apenas em $k$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900009', '$k=2$', 'O parâmetro precisa fazer o par indicado satisfazer todas as equações. Como a segunda já é verdadeira para o par, a primeira determina unicamente o valor necessário de $k$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000091', '40000000-0000-4000-8000-000000900009', 'Confira a equação sem parâmetro', '$2-1=1$, portanto a segunda equação é satisfeita.', 1), ('70000000-0000-4000-8000-000009000092', '40000000-0000-4000-8000-000000900009', 'Substitua na primeira', 'Temos $2k+1=5$.', 2), ('70000000-0000-4000-8000-000009000093', '40000000-0000-4000-8000-000000900009', 'Isole o parâmetro', '$2k=4$, logo $k=2$.', 3), ('70000000-0000-4000-8000-000009000094', '40000000-0000-4000-8000-000000900009', 'Verifique o sistema', 'Com $k=2$, a primeira equação dá $4+1=5$ e o par funciona em ambas.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900010', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'medium', 'published', 'A forma escalonada de um sistema em $x,y,z$ é $\begin{pmatrix}1&0&2&|&4\\0&1&-1&|&3\\0&0&0&|&0\end{pmatrix}$. Qual descrição do conjunto solução é correta?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000101', '40000000-0000-4000-8000-000000900010', 'A', 'O sistema não possui solução.', 1), ('50000000-0000-4000-8000-000009000102', '40000000-0000-4000-8000-000000900010', 'B', '$(x,y,z)=(4-2t,3+t,t)$, $t\in\mathbb R$', 2), ('50000000-0000-4000-8000-000009000103', '40000000-0000-4000-8000-000000900010', 'C', '$(x,y,z)=(4,3,0)$ apenas', 3), ('50000000-0000-4000-8000-000009000104', '40000000-0000-4000-8000-000000900010', 'D', '$(x,y,z)=(4+2t,3-t,t)$, $t\in\mathbb R$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900010', '50000000-0000-4000-8000-000009000102') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900010', '30000000-0000-4000-8000-000000090002', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000101', '40000000-0000-4000-8000-000000900010', 'Colunas sem pivô correspondem a variáveis livres.', 1), ('60000000-0000-4000-8000-000009000102', '40000000-0000-4000-8000-000000900010', 'Escolha um parâmetro para $z$.', 2), ('60000000-0000-4000-8000-000009000103', '40000000-0000-4000-8000-000000900010', 'Isole $x$ e $y$ nas duas linhas não nulas.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900010', '$(x,y,z)=(4-2t,3+t,t)$, $t\in\mathbb R$', 'Há pivôs nas colunas de $x$ e $y$, mas não na de $z$. Assim $z$ é livre e cada escolha do parâmetro produz uma solução, sem qualquer linha contraditória.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000101', '40000000-0000-4000-8000-000000900010', 'Localize os pivôs', 'As duas primeiras colunas têm pivôs; a terceira não tem.', 1), ('70000000-0000-4000-8000-000009000102', '40000000-0000-4000-8000-000000900010', 'Parametrize a variável livre', 'Defina $z=t$.', 2), ('70000000-0000-4000-8000-000009000103', '40000000-0000-4000-8000-000000900010', 'Isole as variáveis básicas', '$x+2t=4$ dá $x=4-2t$, e $y-t=3$ dá $y=3+t$.', 3), ('70000000-0000-4000-8000-000009000104', '40000000-0000-4000-8000-000000900010', 'Apresente e confira', 'A família $(4-2t,3+t,t)$ satisfaz ambas as equações para todo $t$ real.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900011', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'medium', 'published', 'Uma transformação aplica primeiro uma matriz $B$ de ordem $3\times2$ a vetores de $\mathbb R^2$ e depois uma matriz $A$ de ordem $2\times3$. Qual matriz representa a composição e qual é sua ordem?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000111', '40000000-0000-4000-8000-000000900011', 'A', '$AB$, de ordem $3\times3$', 1), ('50000000-0000-4000-8000-000009000112', '40000000-0000-4000-8000-000000900011', 'B', '$A+B$, de ordem $2\times3$', 2), ('50000000-0000-4000-8000-000009000113', '40000000-0000-4000-8000-000000900011', 'C', '$AB$, de ordem $2\times2$', 3), ('50000000-0000-4000-8000-000009000114', '40000000-0000-4000-8000-000000900011', 'D', '$BA$, de ordem $3\times3$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900011', '50000000-0000-4000-8000-000009000113') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900011', '30000000-0000-4000-8000-000000090001', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000111', '40000000-0000-4000-8000-000000900011', 'Na composição, a operação aplicada primeiro aparece mais à direita.', 1), ('60000000-0000-4000-8000-000009000112', '40000000-0000-4000-8000-000000900011', 'A saída de $B$ tem três componentes, compatíveis com a entrada de $A$.', 2), ('60000000-0000-4000-8000-000009000113', '40000000-0000-4000-8000-000000900011', 'As dimensões externas do produto determinam a ordem final.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900011', '$AB$, de ordem $2\times2$', 'Vetores coluna são transformados como $vmapsto Bvmapsto A(Bv)$. A associatividade escreve o resultado como $(AB)v$, e as dimensões externas são duas por duas.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000111', '40000000-0000-4000-8000-000000900011', 'Registre o fluxo', '$B$ leva $\mathbb R^2$ a $\mathbb R^3$ e $A$ leva $\mathbb R^3$ a $\mathbb R^2$.', 1), ('70000000-0000-4000-8000-000009000112', '40000000-0000-4000-8000-000000900011', 'Escreva a composição', 'Aplicar $B$ antes de $A$ produz $A(Bv)$.', 2), ('70000000-0000-4000-8000-000009000113', '40000000-0000-4000-8000-000000900011', 'Associe o produto', '$A(Bv)=(AB)v$.', 3), ('70000000-0000-4000-8000-000009000114', '40000000-0000-4000-8000-000000900011', 'Confira as dimensões', 'O produto $(2\times3)(3\times2)$ tem ordem $2\times2$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900012', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'medium', 'published', 'Considere $A=LU$, com $L=\begin{pmatrix}1&0\\2&1\end{pmatrix}$, $U=\begin{pmatrix}3&1\\0&2\end{pmatrix}$ e $b=(4,10)$. Ao resolver $Ax=b$, qual é $x$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000121', '40000000-0000-4000-8000-000000900012', 'A', '$(4,10)$', 1), ('50000000-0000-4000-8000-000009000122', '40000000-0000-4000-8000-000000900012', 'B', '$(2,-2)$', 2), ('50000000-0000-4000-8000-000009000123', '40000000-0000-4000-8000-000000900012', 'C', '$(0,2)$', 3), ('50000000-0000-4000-8000-000009000124', '40000000-0000-4000-8000-000000900012', 'D', '$(1,1)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900012', '50000000-0000-4000-8000-000009000124') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900012', '30000000-0000-4000-8000-000000090004', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000121', '40000000-0000-4000-8000-000000900012', 'Introduza um vetor intermediário $y$ com $Ly=b$.', 1), ('60000000-0000-4000-8000-000009000122', '40000000-0000-4000-8000-000000900012', 'Resolva primeiro o sistema triangular inferior.', 2), ('60000000-0000-4000-8000-000009000123', '40000000-0000-4000-8000-000000900012', 'Depois use $Ux=y$ por substituição retroativa.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900012', '$(1,1)$', 'A fatoração $LU$ divide o problema em dois sistemas triangulares. Primeiro obtemos o vetor intermediário pela matriz inferior; só então resolvemos o sistema superior para $x$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000121', '40000000-0000-4000-8000-000000900012', 'Resolva $Ly=b$', '$y_1=4$ e $2y_1+y_2=10$, portanto $y=(4,2)$.', 1), ('70000000-0000-4000-8000-000009000122', '40000000-0000-4000-8000-000000900012', 'Monte o segundo sistema', 'Agora resolvemos $Ux=y$.', 2), ('70000000-0000-4000-8000-000009000123', '40000000-0000-4000-8000-000000900012', 'Faça a substituição retroativa', '$2x_2=2$ dá $x_2=1$; então $3x_1+x_2=4$ dá $x_1=1$.', 3), ('70000000-0000-4000-8000-000009000124', '40000000-0000-4000-8000-000000900012', 'Verifique', '$LU(1,1)=L(4,2)=(4,10)=b$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900013', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'hard', 'published', 'Para quais valores de $a$ o sistema $x+ay=1$ e $ax+y=1$ não possui solução única?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000131', '40000000-0000-4000-8000-000000900013', 'A', '$a=1$ ou $a=-1$', 1), ('50000000-0000-4000-8000-000009000132', '40000000-0000-4000-8000-000000900013', 'B', 'Somente $a=1$', 2), ('50000000-0000-4000-8000-000009000133', '40000000-0000-4000-8000-000000900013', 'C', 'Somente $a=0$', 3), ('50000000-0000-4000-8000-000009000134', '40000000-0000-4000-8000-000000900013', 'D', 'Todo $a$ real', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900013', '50000000-0000-4000-8000-000009000131') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900013', '30000000-0000-4000-8000-000000090003', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000131', '40000000-0000-4000-8000-000000900013', 'Solução única equivale a uma matriz de coeficientes invertível.', 1), ('60000000-0000-4000-8000-000009000132', '40000000-0000-4000-8000-000000900013', 'Calcule o determinante da matriz dos coeficientes.', 2), ('60000000-0000-4000-8000-000009000133', '40000000-0000-4000-8000-000000900013', 'Fatore $1-a^2$ antes de analisar os casos.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900013', '$a=1$ ou $a=-1$', 'O sistema perde unicidade exatamente quando sua matriz de coeficientes é singular. Isso inclui tanto o caso de infinitas soluções quanto o caso inconsistente, por isso ambos os valores críticos entram.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000131', '40000000-0000-4000-8000-000000900013', 'Monte a matriz', '$A=\begin{pmatrix}1&a\\a&1\end{pmatrix}$.', 1), ('70000000-0000-4000-8000-000009000132', '40000000-0000-4000-8000-000000900013', 'Use o critério de unicidade', 'Há solução única se e somente se $\det A
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900014', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'hard', 'published', 'Em um nó de uma rede, entram fluxos de $40$ e $x$ unidades por minuto, enquanto saem $25$ e $y$. Em outro nó, entram $y$ e $5$, e saem $3x$ unidades. Se há conservação em ambos, qual é $(x,y)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000141', '40000000-0000-4000-8000-000000900014', 'A', '$(5,20)$', 1), ('50000000-0000-4000-8000-000009000142', '40000000-0000-4000-8000-000000900014', 'B', '$(10,25)$', 2), ('50000000-0000-4000-8000-000009000143', '40000000-0000-4000-8000-000000900014', 'C', '$(25,40)$', 3), ('50000000-0000-4000-8000-000009000144', '40000000-0000-4000-8000-000000900014', 'D', '$(15,30)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900014', '50000000-0000-4000-8000-000009000142') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900014', '30000000-0000-4000-8000-000000090003', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000141', '40000000-0000-4000-8000-000000900014', 'Em cada nó, iguale a soma dos fluxos de entrada à soma dos de saída.', 1), ('60000000-0000-4000-8000-000009000142', '40000000-0000-4000-8000-000000900014', 'O primeiro nó fornece uma relação entre $x$ e $y$.', 2), ('60000000-0000-4000-8000-000009000143', '40000000-0000-4000-8000-000000900014', 'Use a segunda relação para eliminar uma variável.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900014', '$(10,25)$', 'A conservação transforma cada nó em uma equação linear. É essencial manter o sentido dos fluxos: entradas ficam de um lado e saídas do outro antes de resolver o sistema resultante.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000141', '40000000-0000-4000-8000-000000900014', 'Modele o primeiro nó', '$40+x=25+y$, portanto $y=x+15$.', 1), ('70000000-0000-4000-8000-000009000142', '40000000-0000-4000-8000-000000900014', 'Modele o segundo nó', '$y+5=3x$.', 2), ('70000000-0000-4000-8000-000009000143', '40000000-0000-4000-8000-000000900014', 'Combine as relações', 'Substituindo $y=x+15$, obtemos $x+20=3x$, então $x=10$.', 3), ('70000000-0000-4000-8000-000009000144', '40000000-0000-4000-8000-000000900014', 'Recupere e confira', 'Assim $y=25$; nos nós, $50=50$ e $30=30$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900015', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'hard', 'published', 'Uma matriz quadrada satisfaz $A^2-3A+2I=0$. Sabendo que $A$ é invertível, qual expressão representa $A^{-1}$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000151', '40000000-0000-4000-8000-000000900015', 'A', '$\frac{1}{2}(A-3I)$', 1), ('50000000-0000-4000-8000-000009000152', '40000000-0000-4000-8000-000000900015', 'B', '$3I-A$', 2), ('50000000-0000-4000-8000-000009000153', '40000000-0000-4000-8000-000000900015', 'C', '$\frac{1}{2}(3I-A)$', 3), ('50000000-0000-4000-8000-000009000154', '40000000-0000-4000-8000-000000900015', 'D', '$A-3I$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900015', '50000000-0000-4000-8000-000009000153') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900015', '30000000-0000-4000-8000-000000090004', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000151', '40000000-0000-4000-8000-000000900015', 'Procure produzir um fator $A$ multiplicando uma expressão.', 1), ('60000000-0000-4000-8000-000009000152', '40000000-0000-4000-8000-000000900015', 'Reorganize a identidade deixando o termo com $I$ sozinho.', 2), ('60000000-0000-4000-8000-000009000153', '40000000-0000-4000-8000-000000900015', 'Depois multiplique pela inversa de $A$ e isole $A^{-1}$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900015', '$\frac{1}{2}(3I-A)$', 'Uma identidade polinomial pode fornecer a inversa sem escalonamento. Ao fatorar os termos que contêm $A$, obtemos uma matriz que, multiplicada por $A$, produz um múltiplo da identidade.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000151', '40000000-0000-4000-8000-000000900015', 'Reorganize a igualdade', '$A^2-3A=-2I$.', 1), ('70000000-0000-4000-8000-000009000152', '40000000-0000-4000-8000-000000900015', 'Fatore $A$', '$A(A-3I)=-2I$, ou $A(3I-A)=2I$.', 2), ('70000000-0000-4000-8000-000009000153', '40000000-0000-4000-8000-000000900015', 'Normalize o produto', '$A\left[\frac12(3I-A)\right]=I$.', 3), ('70000000-0000-4000-8000-000009000154', '40000000-0000-4000-8000-000000900015', 'Conclua e confira', 'Como $A$ é invertível, a matriz entre colchetes é $A^{-1}$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900016', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'hard', 'published', 'O sistema $x+y=2$, $2x-y=1$ e $3x=\lambda$ deve ser consistente. Qual valor de $\lambda$ é necessário?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000161', '40000000-0000-4000-8000-000000900016', 'A', '$\lambda=1$', 1), ('50000000-0000-4000-8000-000009000162', '40000000-0000-4000-8000-000000900016', 'B', '$\lambda=6$', 2), ('50000000-0000-4000-8000-000009000163', '40000000-0000-4000-8000-000000900016', 'C', '$\lambda=9$', 3), ('50000000-0000-4000-8000-000009000164', '40000000-0000-4000-8000-000000900016', 'D', '$\lambda=3$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900016', '50000000-0000-4000-8000-000009000164') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900016', '30000000-0000-4000-8000-000000090002', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000161', '40000000-0000-4000-8000-000000900016', 'As duas primeiras equações já determinam $x$ e $y$.', 1), ('60000000-0000-4000-8000-000009000162', '40000000-0000-4000-8000-000000900016', 'Some relações convenientes para eliminar $y$.', 2), ('60000000-0000-4000-8000-000009000163', '40000000-0000-4000-8000-000000900016', 'A terceira equação deve concordar com o valor encontrado de $x$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900016', '$\lambda=3$', 'Em um sistema com mais equações do que incógnitas, as equações adicionais precisam ser compatíveis com a solução determinada pelas primeiras. A terceira não cria liberdade; ela impõe uma condição ao parâmetro.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000161', '40000000-0000-4000-8000-000000900016', 'Resolva as duas primeiras', 'Somando as equações, $3x=3$, portanto $x=1$.', 1), ('70000000-0000-4000-8000-000009000162', '40000000-0000-4000-8000-000000900016', 'Encontre a outra incógnita', 'De $x+y=2$, segue $y=1$.', 2), ('70000000-0000-4000-8000-000009000163', '40000000-0000-4000-8000-000000900016', 'Imponha a equação extra', 'A terceira exige $3\cdot1=\lambda$.', 3), ('70000000-0000-4000-8000-000009000164', '40000000-0000-4000-8000-000000900016', 'Verifique todas as linhas', 'Com $\lambda=3$, o par $(1,1)$ satisfaz as três equações.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900017', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'hard', 'published', 'Dois sistemas têm três incógnitas. No sistema I, $\operatorname{posto}(A)=\operatorname{posto}([A|b])=3$. No sistema II, $\operatorname{posto}(A)=2$ e $\operatorname{posto}([A|b])=3$. Qual comparação está correta?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000171', '40000000-0000-4000-8000-000000900017', 'A', 'I tem solução única e II é inconsistente.', 1), ('50000000-0000-4000-8000-000009000172', '40000000-0000-4000-8000-000000900017', 'B', 'Ambos têm solução única.', 2), ('50000000-0000-4000-8000-000009000173', '40000000-0000-4000-8000-000000900017', 'C', 'I é inconsistente e II tem infinitas soluções.', 3), ('50000000-0000-4000-8000-000009000174', '40000000-0000-4000-8000-000000900017', 'D', 'Ambos têm infinitas soluções.', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900017', '50000000-0000-4000-8000-000009000171') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900017', '30000000-0000-4000-8000-000000090002', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000171', '40000000-0000-4000-8000-000000900017', 'Compare primeiro o posto da matriz de coeficientes com o da aumentada.', 1), ('60000000-0000-4000-8000-000009000172', '40000000-0000-4000-8000-000000900017', 'Postos diferentes indicam uma linha contraditória.', 2), ('60000000-0000-4000-8000-000009000173', '40000000-0000-4000-8000-000000900017', 'Quando os postos coincidem com o número de incógnitas, não há variável livre.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900017', 'I tem solução única e II é inconsistente.', 'O critério de Rouché-Capelli separa consistência de unicidade. Postos iguais garantem consistência; o valor comum igual ao número de incógnitas elimina variáveis livres. Postos diferentes tornam o sistema impossível.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000171', '40000000-0000-4000-8000-000000900017', 'Analise o sistema I', 'Os postos são iguais, então o sistema é consistente.', 1), ('70000000-0000-4000-8000-000009000172', '40000000-0000-4000-8000-000000900017', 'Conte variáveis livres em I', 'O posto $3$ coincide com as três incógnitas, logo a solução é única.', 2), ('70000000-0000-4000-8000-000009000173', '40000000-0000-4000-8000-000000900017', 'Analise o sistema II', 'O posto da aumentada excede o de $A$, indicando contradição.', 3), ('70000000-0000-4000-8000-000009000174', '40000000-0000-4000-8000-000000900017', 'Compare', 'Assim, I tem solução única e II não possui solução.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900018', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090001', 'multiple_choice', 'hard', 'published', 'Um estudante afirma que $(ABC)^{-1}=A^{-1}B^{-1}C^{-1}$ para matrizes invertíveis. Qual correção torna a afirmação válida?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000181', '40000000-0000-4000-8000-000000900018', 'A', 'A inversa de um produto nunca existe.', 1), ('50000000-0000-4000-8000-000009000182', '40000000-0000-4000-8000-000000900018', 'B', '$(ABC)^{-1}=C^{-1}B^{-1}A^{-1}$', 2), ('50000000-0000-4000-8000-000009000183', '40000000-0000-4000-8000-000000900018', 'C', '$(ABC)^{-1}=B^{-1}A^{-1}C^{-1}$', 3), ('50000000-0000-4000-8000-000009000184', '40000000-0000-4000-8000-000000900018', 'D', '$(ABC)^{-1}=A^{-1}C^{-1}B^{-1}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900018', '50000000-0000-4000-8000-000009000182') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900018', '30000000-0000-4000-8000-000000090004', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000181', '40000000-0000-4000-8000-000000900018', 'A matriz candidata deve desfazer primeiro a última transformação aplicada.', 1), ('60000000-0000-4000-8000-000009000182', '40000000-0000-4000-8000-000000900018', 'Multiplique o produto por uma candidata e procure cancelamentos adjacentes.', 2), ('60000000-0000-4000-8000-000009000183', '40000000-0000-4000-8000-000000900018', 'Os fatores inversos precisam aparecer ao lado de seus fatores originais.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900018', '$(ABC)^{-1}=C^{-1}B^{-1}A^{-1}$', 'A inversa desfaz uma composição na ordem reversa. Somente a ordem invertida coloca cada matriz ao lado de sua inversa durante a multiplicação, permitindo os cancelamentos que produzem a identidade.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000181', '40000000-0000-4000-8000-000000900018', 'Considere a composição', '$ABC$ aplica $C$, depois $B$ e por fim $A$ a um vetor.', 1), ('70000000-0000-4000-8000-000009000182', '40000000-0000-4000-8000-000000900018', 'Desfaça a última ação', 'Começamos por $A^{-1}$, depois usamos $B^{-1}$ e $C^{-1}$.', 2), ('70000000-0000-4000-8000-000009000183', '40000000-0000-4000-8000-000000900018', 'Escreva como produto à direita', 'Isso corresponde a $C^{-1}B^{-1}A^{-1}$.', 3), ('70000000-0000-4000-8000-000009000184', '40000000-0000-4000-8000-000000900018', 'Verifique', '$(ABC)(C^{-1}B^{-1}A^{-1})=ABIB^{-1}A^{-1}=I$.', 4)
